import os
import subprocess
import tempfile
from configparser import ConfigParser
from dataclasses import dataclass, field

import dulwich.porcelain
import git


TEMPLATES_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "templates")


@dataclass
class GitConfig:
    branch: str = "main"
    depth: int = 1
    template_dir: str = TEMPLATES_DIR
    extra_options: list = field(default_factory=list)


def _apply_template(repo_path, template_dir):
    cfg_path = os.path.join(repo_path, ".git", "config")
    cfg = ConfigParser()
    cfg.read(cfg_path)
    if not cfg.has_section("core"):
        cfg.add_section("core")
    cfg.set("core", "hooksPath", template_dir)
    with open(cfg_path, "w") as f:
        cfg.write(f)

    for entry in os.listdir(template_dir):
        path = os.path.join(template_dir, entry)
        if os.path.isfile(path) and os.access(path, os.X_OK):
            subprocess.run(
                [path],
                cwd=repo_path,
                env={**os.environ, "GIT_DIR": os.path.join(repo_path, ".git")},
            )


def get_git(url, dest=None, config=None):
    if config is None:
        config = GitConfig()
    if dest is None:
        dest = tempfile.mkdtemp(prefix="dynamic-git-")

    dulwich.porcelain.clone(url, dest, branch=config.branch, depth=config.depth)

    if config.template_dir:
        _apply_template(dest, config.template_dir)

    return git.Repo(dest)
